    public int pop() { return remove(size()-1); }
}

5. What is the output?
class Parent {
    public String getType() { return "Parent"; }
    public static String getStatic() { return "Parent-Static"; }
}
class Child extends Parent {
    @Override
    public String getType() { return "Child"; }
    public static String getStatic() { return "Child-Static"; }
}
Parent obj = new Child();
System.out.println(obj.getType());
System.out.println(obj.getStatic());

7. What is the output and why?
class Base {
    int x = 10;
    int getX() { return x; }
}
class Derived extends Base {
    int x = 20;
    @Override int getX() { return x; }
}
Base obj = new Derived();
System.out.println(obj.x);
System.out.println(obj.getX());

